<script lang="ts">// code based on: https://svelte.dev/examples/modal
import { onEscape } from '../../actions/onEscape.js';
import { onDestroy, onMount } from 'svelte';
import { classnames } from '../../utils/cssUtils.js';
export let className = undefined;
export let fullscreen = false;
export let onClose;
let dialog;
onMount(() => dialog.showModal());
onDestroy(() => dialog.close());
function close() {
    onClose();
}
</script>

<dialog
  bind:this={dialog}
  on:close={close}
  on:pointerdown|self={close}
  on:cancel|preventDefault
  use:onEscape={close}
  class={classnames('jse-modal', className)}
  class:jse-fullscreen={fullscreen}
>
  <div class="jse-modal-inner">
    <slot />
  </div>
</dialog>

